<template><div><div class="text-h5 q-mb-md">編輯保單內文</div><q-card><q-card-section><q-form class="q-gutter-md" @submit="form.put(route('admin.insurance-policy-contents.update',contentItem.id))"><q-select v-model="form.insurance_policy_id" :options="policies" label="保單" outlined emit-value map-options :error="!!form.errors.insurance_policy_id" :error-message="form.errors.insurance_policy_id" /><q-input v-model="form.content" label="條款內文" outlined type="textarea" autogrow :error="!!form.errors.content" :error-message="form.errors.content" /><div class="row q-col-gutter-md"><div class="col-12 col-sm-4"><q-input v-model.number="form.page_from" type="number" label="起始頁碼" outlined /></div><div class="col-12 col-sm-4"><q-input v-model.number="form.page_to" type="number" label="結束頁碼" outlined /></div><div class="col-12 col-sm-4"><q-input v-model.number="form.sort_order" type="number" label="排序" outlined /></div></div><div class="text-caption text-grey">內文修改後會自動重新產生向量。</div><div class="row q-gutter-sm"><q-btn type="submit" color="primary" label="更新" :loading="form.processing" /><q-btn flat label="取消" @click="$inertia.visit(route('admin.insurance-policy-contents.index'))" /></div></q-form></q-card-section></q-card></div></template><script setup lang="ts">import{useForm}from'@inertiajs/vue3';import AdminLayout from '../../Layouts/AdminLayout.vue';defineOptions({layout:AdminLayout});const props=defineProps<{contentItem:{id:number;insurance_policy_id:number;content:string;page_from:number|null;page_to:number|null;sort_order:number};policies:{value:number;label:string}[]}>();const form=useForm({insurance_policy_id:props.contentItem.insurance_policy_id,content:props.contentItem.content,page_from:props.contentItem.page_from,page_to:props.contentItem.page_to,sort_order:props.contentItem.sort_order})</script>